import{z as s,x as p,o as t,c as B,q as l,j as E,D as e,d as o,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"持有期与换手","description":"","frontmatter":{"title":"持有期与换手","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/holding-horizon.md","filePath":"quant/holding-horizon.md","lastUpdated":1791413859000}'),d={name:"quant/holding-horizon.md"};function A(h,a,m,u,c,_){const r=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=l('<h1 id="持有期与换手" tabindex="-1">持有期与换手 <a class="header-anchor" href="#持有期与换手" aria-label="Permalink to &quot;持有期与换手&quot;">​</a></h1><div class="epigraph"><p>策略赚的是持有期上的预期收益减去该持有期必须支付的交易摩擦。把日频 alpha 接在五分钟实现价差上，或把年频价值接在盘中价差上，都是把两套时钟焊在一起。</p><footer>—— 据 Hasbrouck 对交易成本与持有期的经验讨论；对照 Novy-Marx and Velikov 对换手与成本后异常的处理</footer></div><p><a href="/quant/realized-spread-horizon">实现价差期限</a>给出了做市商转手窗口上的 \\(\\mathrm{RS}(\\tau)\\)。价格形成课序到此结束。本课打开「持有期与容量」：策略自己的时钟 \\(H\\)——打算持有多久、因此必须换手多快——如何决定它该读价差曲线的哪一段。Novy-Marx 与 Velikov 表明，许多异常在成本之后只对低换手实现成立。缺口不是再分解价差，而是把 \\(H\\) 写成策略的一等参数，并定义换手与之互逆。后课容量、延迟预算、频率体制都默认 \\(H\\) 已经选好。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>微观结构度量活在秒到分钟；因子活在月到年。中间缺一个显式的持有期。同一信号，若每天重配，付的是短 \\(\\tau\\) 上仍未消失的冲击加价差；若季度再平衡，付的是接近永久的冲击加稀少的换手。预期收益若用月度截面、成本若用五分钟有效价差，净 alpha 的符号可以是假的：你没有在五分钟内实现那个月度收益。问题是联合声明 \\((H,\\text{换手},\\text{对照的成本度量})\\)。</p><p>换手不是持有期的倒数那么干净。部分换手来自权重漂移、分红再投资、成份变动，而不是来自信号翻转。有的策略持有期长但名字轮动快（高换手的「长期」主题篮子）。要用双边换手、名称换手、以及加权平均持有期（持仓金额对开仓以来时间的加权）三套数，不能只报「日频策略」。</p><p><span class="marginnote">换手就是「一段时间内买进（或卖出）的金额 ÷ 平均资产规模」。年换手 200% 大致等于每 6 个月把整个组合换一遍，对应持有期约半年；年换手 1200%（月频全重配的量级）对应持有期约一个月还不到。先换算成持有期，再谈成本才有感觉。</span></p><h3 id="持有期决定你消费哪一段摩擦曲线" tabindex="-1">持有期决定你消费哪一段摩擦曲线 <a class="header-anchor" href="#持有期决定你消费哪一段摩擦曲线" aria-label="Permalink to &quot;持有期决定你消费哪一段摩擦曲线&quot;">​</a></h3><p>把成本写成</p> \\[c(H)\\approx \\frac{s_{\\mathrm{e}}}{2}\\cdot \\mathbf{1}_{\\{H\\text{ 短}\\}} + \\Lambda(H)\\cdot \\text{参与率}, \\]<p>其中有效半价差是即时的，\\(H\\) 变长时你更关心永久冲击 \\(\\Lambda\\) 而不是回跳。这不是新公式，只是提醒：先修曲线 \\(\\mathrm{RS}(\\tau)\\) 的 \\(\\tau\\) 应与 \\(H\\) 同阶。日频隔夜策略应对照隔夜截断的冲击；做市应对照下一笔到几分钟的实现价差。用 Amihud 日度 ILLIQ 去惩罚一个持有三秒的回转策略，对象错了。</p><p><span class="marginnote">A 股 T+1 把买入的最短持有期钉在「今晚到明天」。任何声称 \\(H\\lt 1\\) 日的股票多头轮转，必须进入可卖量约束，而不是只在收益序列上平移。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从成交记录估计策略的持有期分布：每笔开仓到平仓的时间、金额加权中位数 \\(H_{50}\\)、以及换手率（一段时期买入与卖出金额相对平均净资产）。把信号按再平衡频率做网格：日、周、月，报告毛收益、换手、用匹配 \\(\\tau\\) 的有效/实现价差加冲击后的净收益。Novy-Marx–Velikov 的精神是：异常的可投资性随换手下降，应在成本后仍显著才进入下一课的容量讨论。</p><p><span class="marginnote">数字实例：日频策略一年约 250 个交易日，每次换手付 5 个基点的半价差，一年就是约 250×0.05%=12.5% 的成本。若信号毛 alpha 只有 8%，信号再准也是亏——这就是为什么成本必须和持有期一起谈。</span></p><p>研究组合常用的「月度排序、持有一个月」已经把 \\(H\\) 钉死。实盘若每日用新权重做部分再平衡，实际 \\(H\\) 更短、换手更高。回测必须用将要部署的再平衡规则，而不是用论文表格的 \\(H\\)。与<a href="/quant/rebalance-rules">再平衡规则</a>的接口是：阈值再平衡拉长有效持有期，降低换手，同时增加跟踪误差。</p><h3 id="换手分解-信号、漂移、公司行为" tabindex="-1">换手分解：信号、漂移、公司行为 <a class="header-anchor" href="#换手分解-信号、漂移、公司行为" aria-label="Permalink to &quot;换手分解：信号、漂移、公司行为&quot;">​</a></h3><p>换手 $= $ 信号翻转 \\(+\\) 价格漂移导致的权重修复 \\(+\\) 公司行为与成份 \\(+\\) 申赎。只压信号翻转不够。价格上涨的名字权变大，若要保持等权，必须卖出赢家——这会把动量的持有期改短。公司行为见后课引擎；在本课只需把除权日的机械换手从「alpha 衰减」里剔除。报告一张分解表，比只报年化换手 80% 更有用。</p>',18)),(t(),E(i,null,{default:e(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20TO%5B%22%E6%80%BB%E6%8D%A2%E6%89%8B%22%5D%20--%3E%20S%5B%22%E4%BF%A1%E5%8F%B7%E7%BF%BB%E8%BD%AC%EF%BC%9Aalpha%20%E6%94%B9%E6%96%B9%E5%90%91%22%5D%0A%20%20TO%20--%3E%20D%5B%22%E4%BB%B7%E6%A0%BC%E6%BC%82%E7%A7%BB%EF%BC%9A%E6%9D%83%E9%87%8D%E5%81%8F%E7%A6%BB%E7%9B%AE%E6%A0%87%22%5D%0A%20%20TO%20--%3E%20C%5B%22%E5%85%AC%E5%8F%B8%E8%A1%8C%E4%B8%BA%E4%B8%8E%E6%88%90%E4%BB%BD%E5%8F%98%E5%8A%A8%22%5D%0A%20%20TO%20--%3E%20F%5B%22%E7%94%B3%E8%B5%8E%E5%B8%A6%E6%9D%A5%E7%9A%84%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%0A%20%20D%20--%3E%20EQ%5B%22%E7%AD%89%E6%9D%83%E9%A1%BB%E5%8D%96%E8%B5%A2%E5%AE%B6%EF%BC%9A%E6%9C%89%E6%95%88%E6%8C%81%E6%9C%89%E6%9C%9F%E8%A2%AB%E6%94%B9%E7%9F%AD%22%5D%0A%20%20C%20--%3E%20MECH%5B%22%E6%9C%BA%E6%A2%B0%E6%8D%A2%E6%89%8B%EF%BC%9A%E5%BA%94%E5%89%94%E5%87%BA%20alpha%20%E8%A1%B0%E5%87%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>持有期通过两个通道进入期望。第一，收益：许多微观 alpha 是短时逆转或订单流，期望在 \\(H\\) 拉长后衰减；价值、质量在 \\(H\\) 太短时付不出换手。第二，成本：摩擦曲线随 \\(\\tau\\) 下降的是暂时项，永久项留下。最优 \\(H\\) 是衰减与成本的交点，不是夏普最大的采样频率。Hasbrouck 强调交易成本必须相对于投资地平线来读；把所有策略丢进同一个五分钟有效价差池，是拒绝做这个交点。</p><p><span class="marginnote">直觉类比：像租房——按天短租单价高，按年长租单价低但要住满。持有期就是租期，成本曲线要按同一租期去问价。拿日内价差去给年频策略算成本，是拿短租价吓唬长租客；反过来用年频冲击给盘中策略算成本，是假装长租价能覆盖开一夜。</span></p><p>频率体制（后课）只是把 \\((H,\\) 延迟，容量）打包命名。本课先把 \\(H\\) 从「我们是日频组」的口头禅变成可估计的分布。</p><p><span class="marginnote">不要用 <a href="/quant/roll-model">Roll</a> 的日度有效价差去成本化一个盘中策略：Roll 吃的是收盘价回跳，地平线是日。也不要把 Kyle 均衡里的单期拍卖当成策略持有期。</span></p>',5)),(t(),E(i,null,{default:e(()=>[n(r,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22%E6%8C%81%E6%9C%89%E6%9C%9F%20H%22%5D%20--%3E%20TO%5B%22%E6%8D%A2%E6%89%8B%22%5D%0A%20%20H%20--%3E%20C%5B%22%E5%AF%B9%E7%85%A7%E6%91%A9%E6%93%A6%E6%9B%B2%E7%BA%BF%E7%9A%84%20%CF%84%E2%89%88H%22%5D%0A%20%20TO%20--%3E%20NET%5B%22%E6%88%90%E6%9C%AC%E5%90%8E%E6%94%B6%E7%9B%8A%22%5D%0A%20%20C%20--%3E%20NET%0A%20%20A%5B%22%E6%AF%9B%20alpha%20%E8%A1%B0%E5%87%8F%22%5D%20--%3E%20NET%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h3 id="信号时钟与执行时钟可以不是同一个" tabindex="-1">信号时钟与执行时钟可以不是同一个 \\(H\\) <a class="header-anchor" href="#信号时钟与执行时钟可以不是同一个" aria-label="Permalink to &quot;信号时钟与执行时钟可以不是同一个 $H$&quot;">​</a></h3><p>月频因子在再平衡日走 VWAP，执行层的持有期是日内切片。净收益会计必须拆开：信号层读日度冲击，执行层读盘中曲线。混成一个 \\(H\\)，成本会对不齐。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>衍生品的持有期还受到期约束；期货展期把 \\(H\\) 切成合约段。债券买入持有可以是年，但中间的 OTC 变现时间是流动性风险，见 TRACE 课，不要用股票有效价差去代理。本课不估计策略能管多少钱——那是容量；也不分配毫秒预算——那是延迟。</p><p><span class="marginnote">衍生品到期会强制切断 \\(H\\)。把期权当股票一样的「持有一个月」，会忽略 gamma 与交割。体制卡要写清资产类约束。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持有期 \\(H\\) 决定读摩擦曲线的哪一段，以及毛 alpha 能活多久。</li><li>换手与 \\(H\\) 相关但不等价，要分解信号、漂移与公司行为。</li><li>成本度量的 \\(\\tau\\) 必须与 \\(H\\) 同阶；T+1 钉死股票多头的下限。</li><li>再平衡规则改变有效 \\(H\\)，回测须与部署一致。</li><li>下一课在给定 \\(H\\) 上问能做多大。</li><li>出处：Novy-Marx and Velikov, <em>RFS</em>, 2016；Hasbrouck 对交易成本与地平线的论述；再平衡与换手见投资组合课序。</li></ul>',7))])}const T=s(d,[["render",A]]);export{C as __pageData,T as default};
